import openpyxl
wb=openpyxl.load_workbook('/root/data/workbook.xlsx', data_only=False)
found=[]
for s in wb.sheetnames:
    ws=wb[s]
    for row in ws.iter_rows():
        for cell in row:
            v=cell.value
            if isinstance(v,str) and '_xlfn' in v:
                found.append((s, cell.coordinate, v))
print('found', len(found))
for item in found[:50]:
    print(item)
PY
